package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.service.PlantService;import org.nonfood.oilplants.util.ResultFields;import java.io.*;import java.util.*;import java.util.logging.*;
@WebServlet("/plants") public class PlantSearchServlet extends HttpServlet{private static final Logger LOG=Logger.getLogger(PlantSearchServlet.class.getName());protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{PlantService svc=new PlantService();var criteria=svc.criteria(r.getParameterMap());var page=svc.dao().search(criteria,false);r.setAttribute("pageData",page);r.setAttribute("criteria",criteria);r.setAttribute("fields",ResultFields.validate(r.getParameterValues("field")));try{SearchHistorySupport.saveIfRequested(r,"BASIC","/plants",false);}catch(Exception historyError){LOG.log(Level.WARNING,"Could not save opted-in search history",historyError);}WebSupport.view(r,s,"plants/search");}catch(IllegalArgumentException e){r.setAttribute("error",e.getMessage());r.setAttribute("fields",ResultFields.DEFAULT);WebSupport.view(r,s,"plants/search");}catch(Exception e){LOG.log(Level.SEVERE,"Plant search failed",e);s.setStatus(HttpServletResponse.SC_SERVICE_UNAVAILABLE);r.setAttribute("error","检索暂时不可用。请稍后重试，或检查数据库连接状态。");r.setAttribute("fields",ResultFields.DEFAULT);WebSupport.view(r,s,"plants/search");}}}
